const d = $input.first().json;
const marcusCtx = $('Parse Marcus Output').first().json;
let preview;
try {
  const raw = d.content[0].text.replace(/```json\n?/g,'').replace(/```\n?/g,'').trim();
  preview = JSON.parse(raw);
} catch(e) {
  preview = { summary: '(Preview unavailable)', quality_flags: [], recommendation: 'needs_review', reasoning: 'Parse error' };
}

const flags = preview.quality_flags?.length > 0
  ? preview.quality_flags.map(f => `- ${f}`).join('\n')
  : '- No flags identified';

const previewMd = `**Taylor Preview (AI)**\n\n**Summary:** ${preview.summary}\n\n**Quality Flags:**\n${flags}\n\n**Recommendation:** ${preview.recommendation}\n**Reasoning:** ${preview.reasoning}`;

return [{ json: { ...marcusCtx, taylor_preview_md: previewMd, taylor_preview_json: preview } }];

const webhook = $input.first().json;
const ctx = JSON.parse($('Create Marcus Review').first().json._ctx || '{}');

const decision = webhook.data?.marcus_decision || webhook.marcus_decision || '';
const notes = webhook.data?.marcus_notes || webhook.marcus_notes || '';

return [{ json: { ...ctx, marcus_decision: decision, marcus_notes: notes } }];

const d = $input.first().json;
if ((d.iterations_marcus || 0) >= 3) {
  throw new Error('Marcus revision limit (3) reached. Manual intervention required.');
}
return [{ json: {
  ...d,
  iterations_marcus: (d.iterations_marcus || 0) + 1,
  marcus_feedback: d.marcus_notes || ''
}}];

const d = $input.first().json;
const prompt = `You are Taylor, final QC reviewer at Relay.

Original Brief: ${d.topic_hint}
Platform: ${d.platform}

### Brand Context
${d.brand_guide}

### Platform Context
${d.platform_playbook}

Post Copy:
${d.post_copy}

Image Direction:
${d.image_direction}

Task: Review the post for quality, brand fit, and platform compliance.

Provide:
1. **Summary** (2-3 sentences describing what the post says and what it's trying to do)
2. **Quality Flags** (list any issues: tone misalignment, platform spec violations, brand inconsistency, generic messaging)
3. **AI Recommendation** (approve | needs_revision | reject_to_sofia)
4. **Brief reasoning** (1 sentence why)

Be strict on brand fit. Posts should feel written specifically for Loopin, not generic SaaS copy.`;

return [{ json: { ...d, taylor_prompt: prompt } }];

const d = $input.first().json;
const ctx = $('Build Taylor Prompt').first().json;
const rawText = d.content[0].text;

const summaryMatch = rawText.match(/\*\*Summary\*\*[:\s]*([\s\S]*?)(?=\*\*Quality Flags|$)/i);
const flagsMatch = rawText.match(/\*\*Quality Flags\*\*[:\s]*([\s\S]*?)(?=\*\*AI Recommendation|$)/i);
const recMatch = rawText.match(/\*\*AI Recommendation\*\*[:\s]*(approve|needs_revision|reject_to_sofia)/i);
const reasonMatch = rawText.match(/\*\*Brief reasoning\*\*[:\s]*([\s\S]*?)$/i);

return [{ json: {
  ...ctx,
  ai_summary: summaryMatch ? summaryMatch[1].trim() : rawText,
  ai_flags: flagsMatch ? flagsMatch[1].trim() : '',
  ai_recommendation: recMatch ? recMatch[1].trim() : 'needs_revision',
  ai_reasoning: reasonMatch ? reasonMatch[1].trim() : ''
}}];

const webhook = $input.first().json;
const ctx = JSON.parse($('Create Taylor Review').first().json._ctx || '{}');

const decision = webhook.data?.taylor_decision || webhook.taylor_decision || '';
const notes = webhook.data?.taylor_notes || webhook.taylor_notes || '';

return [{ json: { ...ctx, taylor_decision: decision, taylor_notes: notes } }];

const d = $input.first().json;
return [{ json: {
  ...d,
  marcus_feedback: `Taylor review feedback:\n${d.taylor_notes || ''}`,
  iterations_marcus: (d.iterations_marcus || 0) + 1
}}];

const d = $input.first().json;
return [{ json: {
  ...d,
  sofia_feedback: `Quality concern from Taylor: ${d.taylor_notes || ''}`,
  iterations_sofia: (d.iterations_sofia || 0) + 1,
  marcus_feedback: ''
}}];
